query RaceMeetingProfile($date: String, $oddsTypes: [OddsType], $venueCode: String) {
    raceMeetingProfile(date: $date, venueCode: $venueCode) {
      races {
        runners {
          jockey {
            id
            code
            name_en
            name_ch
            status
          }
          trainer {
            id
            code
            name_en
            name_ch
          }
          horse {
            name_en
            name_ch
            id
          }
          id
          no
          winOdds
          status
        }
        distance
        raceClass_en
        raceClass_ch
        no
        raceTrack {
          code
          description_en
          description_ch
        }
        id
        raceName_en
        raceName_ch
        status
      }
      venueCode
      date
      status
      pmPools(oddsTypes: $oddsTypes) {
        status
        sellStatus 
        id 
        leg {
          number
          races
        }
        oddsNodes {
          oddsValue 
          combString
          hotFavourite
        }
      }
      changeHistories {
        type
        raceNo
        runnerNo
      }
    } 
  }
